def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    # find full single-colour lines; their colour is the divider colour
    cand = []
    for y in range(H):
        if np.all(g[y] == g[y, 0]):
            cand.append(int(g[y, 0]))
    for x in range(W):
        if np.all(g[:, x] == g[0, x]):
            cand.append(int(g[0, x]))
    dc = max(set(cand), key=cand.count) if cand else 5
    drows = set(y for y in range(H) if np.all(g[y] == dc))
    dcols = set(x for x in range(W) if np.all(g[:, x] == dc))

    def bands(n, divs):
        res, cur = [], []
        for i in range(n):
            if i in divs:
                if cur:
                    res.append(cur)
                cur = []
            else:
                cur.append(i)
        if cur:
            res.append(cur)
        return res

    rb = bands(H, drows)
    cb = bands(W, dcols)
    targets = [(rb[0], cb[0], 1),
               (rb[len(rb) // 2], cb[len(cb) // 2], 2),
               (rb[-1], cb[-1], 3)]
    names = {1: "top-left", 2: "centre", 3: "bottom-right"}
    for rows, cols, col in targets:
        for y in rows:
            for x in cols:
                out[y, x] = col
        emit(out.copy(), f"Fill the {names[col]} lattice cell (rows {rows[0]}-{rows[-1]}, cols {cols[0]}-{cols[-1]}) with colour {col}.")
    return out
